require.config({
  paths: {
    pageRelation: new XWiki.Document(XWiki.Model.resolve('OpenProject.Code.PageRelationLoadJSX',
      XWiki.EntityType.DOCUMENT, XWiki.currentDocument.documentReference)).getURL('jsx', 'r=1')
  }
});
require(['deferred!ckeditor', 'jquery', 'pageRelation'], function (ckeditorPromise, $, pageRelation) {
  const search = function (text, callback, instance) {
    let cfg = { query: { filters: [{ property: "summary", constraints: [{ operator: "contains", value: text }] }] } };
    const searchURL = XWiki.contextPath + '/rest/wikis/' + XWiki.currentWiki + '/projectmanagement/openproject/workitems';
    $.getJSON(searchURL, { instance: instance, filter: JSON.stringify(cfg)})
      .then(function (results) {
        if (Array.isArray(results.items)) {
          results = results.items.map(wp => {
            return {
              id: wp.identifier.value,
              value: wp.identifier.value,
              label: wp.summary.value,
              typebadge: wp.type,
              projectbadge: wp.project.value,
              // The selected text is replaced with nothing and then the macro is inserted, after the autocomplete
              // panel is closed. Using a command instead of the outputTemplate also works on XWiki versions where
              // AdvancedAutoComplete ignores the outputTemplate (e.g. 15.10).
              command: {
                name: 'xwiki-macro-insert',
                data: {
                  name: 'openproject',
                  inline: 'enforce',
                  parameters: {
                    instance: instance,
                    identifier: wp.identifier.value,
                    workItemsDisplayer: 'workItemInline'
                  }
                }
              }
            };
          });
          callback(results);
          return;
        } else {
          callback([]);
        }
      })
      .catch(function (e) {
        console.log(`error trying to retrieve selectize searchUrl ${searchURL} elements.` + e);
        callback([]);
      });
  };
  const DEFAULT_MARKER = '#';
  let markerPromise;
  // The marker is configured by the wiki administrators. It is fetched at runtime (once per page load) instead of
  // being rendered in this skin extension, because the skin extension is cached by the browser.
  const getMarker = function () {
    if (!markerPromise) {
      const configReference = XWiki.Model.resolve('OpenProject.Code.OpenProjectConfiguration',
        XWiki.EntityType.DOCUMENT, XWiki.currentDocument.documentReference);
      const url = new XWiki.Document(configReference).getRestURL(
        'objects/OpenProject.Code.OpenProjectConfigurationClass/0/properties/workPackageSearchMarker');
      markerPromise = Promise.resolve($.getJSON(url, { media: 'json' }))
        .then(property => {
          const marker = typeof property?.value === 'string' ? property.value.trim() : '';
          return marker || DEFAULT_MARKER;
        })
        .catch(() => DEFAULT_MARKER);
    }
    return markerPromise;
  };
  ckeditorPromise.then(ckeditor => {
    function getOpenProjectPluginCfg(marker) {
      return {
        dataCallback: function (options, callback) {
          // Remove the marker prefix and replace non-breaking space.
          const text = options.query.substring(marker.length).replaceAll('\u00A0', ' ');
          pageRelation.get().done(function (relation) {
            if (!relation || !relation.clientParams || !relation.clientParams.instance) {
              console.warn('There is no instance stored in the page relation.');
              return;
            }
            search(text, callback, relation.clientParams.instance);
          });
        },
        marker: marker,
        minChars: 3,
        itemsLimit: 10,
        itemTemplate:
          `<li data-id="{id}" class="ckeditor-autocomplete-item">
            <div class="ckeditor-autocomplete-item-head">
              <span class="ckeditor-autocomplete-item-label">{label}</span>
            </div>
            <div class="ckeditor-autocomplete-item-badges">
              <span class="badge ckeditor-autocomplete-item-badge">{typebadge}</span>
              <span class="badge ckeditor-autocomplete-item-badge">{projectbadge}</span>
            </div>
          </li>`
      };
    }

    // Enable the plugin for the CKEditor instances that have been already created.
    Object.values(ckeditor.instances).forEach(maybeEnableOpenProjectPlugin);
    // Enable the plugin for the CKEditor instances that are going to be created from now on.
    ckeditor.on('instanceCreated', (event) => {
      maybeEnableOpenProjectPlugin(event.editor);
    });

    function maybeEnableOpenProjectPlugin(editor) {
      return Promise.all([waitForEditorReady(editor), getMarker()]).then(([editor, marker]) => {
        new CKEDITOR.plugins.AdvancedAutoComplete(editor, getOpenProjectPluginCfg(marker));
        return editor;
      });
    }

    function waitForEditorReady(editor) {
      return new Promise((resolve, reject) => {
        if (editor.status === 'ready') {
          resolve(editor);
        } else {
          editor.once('instanceReady', (event) => {
            resolve(event.editor);
          });
        }
      });
    }
  });
});
